const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','panels.js','deck-midi.js','midi.js','loop-pads.js','beatgrid.js','loop-ui-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f)).arrayBuffer())])));
async function until(fn,label,ms=12000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);};
const button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`;
function add(target,ch,n){field('#midi-target',target);field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding','7-bit absolute');click('#midi-add');}
function send(ch,n,value=127){field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');}
function press(ch,n){send(ch,n);send(ch,n,0);}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
function measure(data,sr,from,to){let power=0;const crossings=[],start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=data.length&&end>start,'Invalid measurement window');for(let i=start;i<end;i++){power+=data[i]**2;if(i>start&&data[i-1]<0&&data[i]>=0)crossings.push((i-1-data[i-1]/(data[i]-data[i-1]))/sr);}return{from,to,rms:Math.sqrt(power/(end-start)),hz:crossings.length>3?(crossings.length-1)/(crossings.at(-1)-crossings[0]):null};}
let app;
async function run(){
 $('#loop-run').disabled=true;const {engine,state}=app,d=state.decks[0];
 const report={startedAt:new Date().toISOString(),completed:false,scope:'Actual app loop UI, synthetic pointer/keyboard events and master recording. No native, physical controls or full transport-composition acceptance.',criteria:{frequencyErrorHz:.8,playingMinimumRMS:.005,returnPositionToleranceSeconds:.05},events:[],checks:[],errors:[]};
 const event=name=>{const e={name,time:engine.ctx.currentTime-engine.recordStarted};report.events.push(e);return e;};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');
  state.settings['Show Beat Jump Controls']=false;
  for(let n=0;n<2;n++){
   const deck=state.decks[n],buffer=engine.ctx.createBuffer(2,48000*20,48000),data=buffer.getChannelData(n);
   for(let i=0;i<data.length;i++)data[i]=.12*Math.sin(2*Math.PI*(n?550:(i<48000?320:640))*i/48000);
   Object.assign(deck.track,{bpm:120,grid:0,gridWarpMarkers:[],duration:20,analyzed:true,sampleGain:0});Object.assign(deck,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,stemSlip:'off',slip:false,sync:false,level:.8});engine.clearDeckScratchCache(n);engine.buffers.set(deck.track.id,buffer);engine.mix(n,'level',.8);await engine.seek(deck,n?0:.2);
  }
  const control=a=>button(0,a),pad=n=>`[data-deck="0"][data-action="pad"][data-pad="${n}"]`,mode=m=>`[data-deck="0"][data-action="loopMode"][data-mode="${m}"]`;
  click('[data-action="tab"][data-deck="0"][data-tab="Loops"]');click(mode('auto'));click(control('loopRangeUp'));assert($(pad(2)).textContent.includes('1 beats'),'Visible range did not change');click(control('loopRangeDown'));assert($(pad(2)).textContent.includes('0.5 beats'),'Visible half-beat pad missing');
  click(button(0,'play'));click(button(1,'play'));await until(()=>state.decks.slice(0,2).every(d=>d.playing),'Two real decks');
  await engine.recordStart();await engine.seek(d,.2);click(pad(2));await until(()=>d.loop,'UI Auto Loop');assert(d.loopIn===0&&d.loopOut===.25,'UI loop bounds');assert($(pad(2)).getAttribute('aria-pressed')==='true','Auto pad pressed state');event('auto-start');await sleep(650);const auto=event('auto-repeated');await sleep(240);$(pad(2)).dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));await until(()=>!d.loop,'Keyboard Auto Loop exit');assert(d.playing,'Auto Loop keyboard activated Play instead');await sleep(1100);const linear=event('linear-past-one-second');await sleep(240);
  await engine.seek(d,.2);click(mode('roll'));const target=$(pad(2));target.focus();const start=engine.ctx.currentTime,position=engine.position(d);target.dispatchEvent(new KeyboardEvent('keydown',{key:' ',bubbles:true,cancelable:true}));await until(()=>d.loop,'Keyboard Roll');assert(document.activeElement?.dataset.pad==='2','Focus lost during Roll render');assert($(pad(2)).getAttribute('aria-pressed')==='true'&&$(pad(1)).getAttribute('aria-pressed')==='false','Roll size pressed state');await sleep(650);const rolling=event('roll-repeated');await sleep(650);document.dispatchEvent(new KeyboardEvent('keyup',{key:' ',bubbles:true}));await until(()=>!d.loop,'Keyboard Roll release');report.roll={expected:position+engine.ctx.currentTime-start,returned:engine.position(d)};assert(Math.abs(report.roll.returned-report.roll.expected)<.05,'UI Roll continuing clock');const returned=event('roll-return');await sleep(250);
  click(button(0,'play'));click(button(1,'play'));await until(()=>state.decks.slice(0,2).every(d=>!d.playing),'Pause both decks');
  d.track.savedLoops[0]={start:3,end:4,name:'Prior loop fixture'};click(mode('saved'));click(pad(0));await until(()=>d.loop&&d.loopIn===3&&d.loopOut===4,'Saved loop');
  const hold=()=>$(control('roll')).dispatchEvent(new PointerEvent('pointerdown',{pointerId:31,button:0,bubbles:true,cancelable:true}));hold();await sleep(20);assert(d.loopOut-d.loopIn===.25,'Shared Hold Roll size');document.dispatchEvent(new PointerEvent('pointercancel',{pointerId:31,bubbles:true}));await until(()=>d.loopIn===3&&d.loopOut===4,'Pointer cancel restores loop');hold();await sleep(20);window.dispatchEvent(new Event('blur'));await until(()=>d.loopIn===3&&d.loopOut===4,'Blur restores loop');report.priorLoop={start:d.loopIn,end:d.loopOut,position:engine.position(d),playing:d.playing};
  state.settings['Show Beat Jump Controls']=true;click(mode('auto'));assert($(pad(4)).textContent.includes('Jump back'),'Beat Jump row');click(pad(5));await until(()=>d.beatJumpLength===2,'Half jump size');assert($(pad(4)).textContent.includes('2 beats'),'Jump label stale');click(pad(6));await until(()=>d.beatJumpLength===4,'Double jump size');report.beatJump={length:d.beatJumpLength,label:$(pad(4)).textContent};click(mode('roll'));
  const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};const decoded=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:decoded.duration,sampleRate:decoded.sampleRate,frames:decoded.length,channels:decoded.numberOfChannels};assert(decoded.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of decoded.getChannelData(c))assert(Number.isFinite(v),'Nonfinite PCM');
  report.audio=[['auto',auto,320],['linear',linear,640],['rolling',rolling,320],['returned',returned,640]].map(([name,e,left])=>({name,expected:[left,550],channels:[0,1].map(c=>measure(decoded.getChannelData(c),decoded.sampleRate,e.time+.06,e.time+.18))}));for(const w of report.audio)w.channels.forEach((m,c)=>assert(m.rms>.005&&Math.abs(m.hz-w.expected[c])<.8,w.name+' expected audio carrier'));
  report.checks=['Visible range and Auto Loop real transport/pressed state','Focused keyboard Roll and continuing source return','Pointer cancel and blur restore existing loop','Beat Jump row resizes with updated labels; recorded carriers on both decks'];
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  for(const d of state.decks)engine.pause(d);if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};}}report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#loop-original').textContent=JSON.stringify(report,null,2);$('#loop-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original JSON'}:null},null,2);$('#loop-status').textContent=report.completed?'Scoped loop-pad workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');
 }
}
$('#loop-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#loop-run').disabled=false;$('#loop-run').textContent='Run one loop UI workflow';}
boot().catch(error=>$('#loop-status').textContent=error.message);
